UPDATE sys_file_resource SET status = #{nextStatus}, consumed_at = CASE WHEN #{nextStatus} = #{inUseStatus} THEN #{now} ELSE consumed_at END, delete_requested_at = CASE WHEN #{nextStatus} IN (#{deletePendingStatus}, #{expiredStatus}) THEN #{now} ELSE delete_requested_at END, deleted_at = CASE WHEN #{nextStatus} = #{deletedStatus} THEN #{now} ELSE deleted_at END, deleted = CASE WHEN #{nextStatus} = #{deletedStatus} THEN 1 ELSE deleted END, updated_at = #{now}, version = version + 1 WHERE id = #{fileId} AND status IN
#{status}
AND deleted = 0

