WITH candidates AS ( SELECT r.id FROM sys_file_resource r WHERE r.deleted = 0 AND ( r.status IN
#{status}
OR (r.status = #{deletingStatus} AND r.updated_at <= #{leaseExpiredBefore}) ) ORDER BY COALESCE(r.delete_requested_at, r.updated_at), r.id FOR UPDATE SKIP LOCKED LIMIT #{limit} ), claimed AS ( UPDATE sys_file_resource r SET status = #{deletingStatus}, updated_at = #{claimedAt}, version = r.version + 1 FROM candidates c WHERE r.id = c.id RETURNING r.* ) SELECT FROM claimed r JOIN sys_file_object o ON o.file_id = r.id ORDER BY COALESCE(r.delete_requested_at, r.updated_at), r.id

mapper.update:
UPDATE sys_file_resource
SET status = #{nextStatus},
    deleted_at = CASE WHEN #{nextStatus} = #{deletedStatus} THEN #{finishedAt} ELSE deleted_at END,
    deleted = CASE WHEN #{nextStatus} = #{deletedStatus} THEN 1 ELSE deleted END,
    updated_at = #{finishedAt},
    version = version + 1
WHERE id = #{fileId}
AND status = #{deletingStatus}
AND updated_at = #{claimedAt}
AND deleted = 0
